const fs = require("fs");
const path = require("path");
const childProcess = require("child_process");

const env = require("../../util/env-util");
const Demucs = require('../../util/demucs');
const FFmpegUtil = require('../../util/ffmpeg-util');
const TempFolder = require('../../util/temp-folder');
const downloadAttachments = require('../../util/download-attachments');

class Command {
    constructor() {
        this.name = "splitstems";
        this.description = "Split an audio file to 6 musical stems";
        this.descriptionLong = "Split an audio file into stems, like musicaudio files"
            + "\n" + "By default, splits into 6 stems:"
            + "\n" + "`drums`, `bass`, `other`, `guitar`, `piano`, `vocals`"
            + "\n" + "If you specify 4, it's split into:"
            + "\n" + "`drums`, `bass`, `other`, `vocals`"
            + "\n" + "Any other value is invalid dont use them";
        this.attributes = {
            unlisted: false,
            permission: 0,
            lockedToCommands: true,
            numberConversion: true,
        };

        this.alias = ["splitstem", "stemsplit", "stemsplitter", "stemssplitter", "stemssplit"];
        this.example = [
            { text: "{{prefix}}splitstems" },
            { text: "{{prefix}}splitstems 6" },
            { text: "{{prefix}}splitstems 4" },
        ];
    }

    async handle(message, args, util) {
        // get attachements
        const attachment = message.attachments.first();
        if (!attachment) throw new Error("Add an Audio to split");
        const endingType = util.getAttachmentType(attachment);
        if (!FFmpegUtil.isCompatibleAudio(endingType)) throw new Error('Please use a valid audio format.');
        // check atachemtn size
        if (attachment.size > 15 * 1e+6) throw new Error("Files must be below 15 MB.");

        const stemCount = args.shift() || 6;
        if (stemCount !== 4 && stemCount !== 6)
            throw new Error("Invalid stem count; see help for this command");

        // actually start doing stuff
        const startTime = Date.now();
        const jobName = TempFolder.makeTempName("splitstems");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            // download
            const replyMessage = await message.reply("Downloading contents...");
            const [rawInputPath] = await downloadAttachments([attachment], (i) => `input${i}.bin`, tempDir);
            // convert to safe type
            await replyMessage.edit("Converting contents...");
            const inputPath = path.join(tempDir, `inputsafe.ogg`);
            await FFmpegUtil.commands.convertToSafeOgg(rawInputPath, inputPath);
            // check length
            const length = await FFmpegUtil.probe.length(inputPath);
            if (length > 10 * 60) return replyMessage.edit("Files must be within 10 minutes long OR you can buy me 64 gigabytes of ram 🎉");

            // generate
            await replyMessage.edit(`Splitting audio into ${stemCount} stems with demucs...`);
            if (stemCount === 4) {
                const [
                    outputPathDrums,
                    outputPathBass,
                    outputPathOther,
                    outputPathVocals
                ] = await Demucs.splitStems(inputPath, tempDir);

                // ok now we convert that to ogg because its too big
                await replyMessage.edit("Converting to OGG... (because wav files are Fat)");
                const outputPathOggDrums = path.join(tempDir, "drums.ogg");
                const outputPathOggBass = path.join(tempDir, "bass.ogg");
                const outputPathOggOther = path.join(tempDir, "other.ogg");
                const outputPathOggVocals = path.join(tempDir, "vocals.ogg");
                await FFmpegUtil.commands.convertToSafeOgg(outputPathDrums, outputPathOggDrums);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathBass, outputPathOggBass);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathOther, outputPathOggOther);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathVocals, outputPathOggVocals);

                await replyMessage.edit({
                    content: "Completed in " + ((Date.now() - startTime) / 1000) + " seconds"
                        + "\n" + `-# Generated by <@${message.author.id}>`,
                    files: [
                        outputPathOggDrums,
                        outputPathOggBass,
                        outputPathOggOther,
                        outputPathOggVocals,
                    ]
                });
            } else {
                const [
                    outputPathDrums,
                    outputPathBass,
                    outputPathOther,
                    outputPathGuitar,
                    outputPathPiano,
                    outputPathVocals
                ] = await Demucs.split6Stems(inputPath, tempDir);

                // ok now we convert that to ogg because its too big
                await replyMessage.edit("Converting to OGG... (because wav files are Fat)");
                const outputPathOggDrums = path.join(tempDir, "drums.ogg");
                const outputPathOggBass = path.join(tempDir, "bass.ogg");
                const outputPathOggOther = path.join(tempDir, "other.ogg");
                const outputPathOggGuitar = path.join(tempDir, "guitar.ogg");
                const outputPathOggPiano = path.join(tempDir, "piano.ogg");
                const outputPathOggVocals = path.join(tempDir, "vocals.ogg");
                await FFmpegUtil.commands.convertToSafeOgg(outputPathDrums, outputPathOggDrums);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathBass, outputPathOggBass);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathOther, outputPathOggOther);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathGuitar, outputPathOggGuitar);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathPiano, outputPathOggPiano);
                await FFmpegUtil.commands.convertToSafeOgg(outputPathVocals, outputPathOggVocals);

                await replyMessage.edit({
                    content: "Completed in " + ((Date.now() - startTime) / 1000) + " seconds"
                        + "\n" + `-# Generated by <@${message.author.id}>`,
                    files: [
                        outputPathOggDrums,
                        outputPathOggBass,
                        outputPathOggOther,
                        outputPathOggGuitar,
                        outputPathOggPiano,
                        outputPathOggVocals,
                    ]
                });
            }
        });
    }
    async invoke(message, args, util) {
        const canDo = util.request("heavyExternalStuff");
        if (!canDo) return message.reply("disabled (im probably playing a game)");

        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;